import{z as B,x as i,o as A,c as p,q as r,j as s,D as l,d as t,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SFT 对 RL 的数据效率","description":"","frontmatter":{"title":"SFT 对 RL 的数据效率","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sft-vs-rl-efficiency.md","filePath":"llm/sft-vs-rl-efficiency.md","lastUpdated":1791063341000}'),F={name:"llm/sft-vs-rl-efficiency.md"};function T(d,a,S,f,m,P){const e=i("Mermaid");return A(),p("div",null,[a[2]||(a[2]=r('<h1 id="sft-对-rl-的数据效率" tabindex="-1">SFT 对 RL 的数据效率 <a class="header-anchor" href="#sft-对-rl-的数据效率" aria-label="Permalink to &quot;SFT 对 RL 的数据效率&quot;">​</a></h1><div class="epigraph"><p>示范告诉模型「像这样写」；奖励告诉模型「在这个方向上更好」。格式与口吻上，精选 SFT 往往更省标注；要探索示范里没有的推理链，RL 用同一批提示可以走得更远。</p><footer>—— Ouyang 等 InstructGPT（NeurIPS 2022）的阶段分工；Zhou 等 LIMA（2023）的样本效率；对照后续偏好与 RL 文献</footer></div><p><a href="/llm/domain-adaptation-ft">领域适配</a>把分布适应和接口对齐拆开。下一步要决定：<strong>接口对齐该花在示范上还是奖励上</strong>。InstructGPT 的顺序是 SFT → 奖励模型 → PPO；<a href="/llm/lima">LIMA</a> 表明千条精选示范已能学会助手表层；开源则大量停在 SFT。本课写二者的数据效率分界，不把拒绝采样循环（<a href="/llm/rft-data-loop">下一课</a>）的工程细节写满。链到已有 <a href="/llm/instructgpt">InstructGPT</a>、<a href="/llm/ppo-llm">PPO</a>、<a href="/llm/dpo">DPO</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SFT 最大化示范上的 \\(p_\\theta(y\\mid x)\\)，样本效率在「\\(y\\) 已经是对的、且覆盖需要的模式」时很高：再标一千条同类示范，边际收益迅速下降。RL（含 PPO 与偏好方法）优化的是奖励或偏好的期望，同一提示可采样许多 \\(y\\)，用分数排序，不必每条都由人写完整答案。代价是：要有奖励信号、要控 KL、要算力，且奖励错了会 Goodhart。</p><p>分界问的不是「SFT 过时了吗」，而是：当前缺口是<strong>没见过正确格式</strong>，还是<strong>见过格式但不会在测试难度上搜索</strong>。前者 SFT 更省；后者堆 SFT 等于让模型背现成链，出分布即断。</p><p><span class="marginnote">术语翻译：SFT 是「照着标准答案逐字模仿」的监督学习，最大化写出示范原文的概率；RL 是「只打分、不给范文」——同一道题让模型自己写很多份，按分数高低调整。前者学「怎么写」，后者学「哪种写法更好」。</span></p><h3 id="表层对齐与可验证任务不是同一预算" tabindex="-1">表层对齐与可验证任务不是同一预算 <a class="header-anchor" href="#表层对齐与可验证任务不是同一预算" aria-label="Permalink to &quot;表层对齐与可验证任务不是同一预算&quot;">​</a></h3><p>LIMA 的主张针对开放助手口吻：能力在预训练里，后训练选接口。数学、代码、可编译工具调用则有外部验证器，RL 可以把对错变成密集或稀疏奖励，用同一题生成大量尝试。把 LIMA 的「一千条够了」抄到竞赛数学上，是换了题目；把 PPO 用在只缺客套语的客服上，是用昂贵探索学一个 SFT 就能写死的模板。</p><p><span class="marginnote">Ouyang 等人用人写 SFT 打底，再 RLHF 改偏好。SFT 不是 RL 的失败模式，是策略的可行起点：从基座直接 PPO 往往不会说话。效率比较应在「已经会 SFT 格式」之后，看额外偏好对或奖励步带来多少增益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先用<a href="/llm/instruction-data-lineage">谱系</a>里合适的示范做 SFT，<a href="/llm/response-only-loss">仅回复</a>，\\(\\eta\\) 按<a href="/llm/lora-vs-full-lr">参数化</a>。这一阶段的目标是：模板正确、拒答与工具分隔出现、不要明显有害。数据以质量为先，条数服从覆盖，不服从「必须十万」。</p><p>若产品指标是偏好（更有用、更少谄媚）且没有单元测试：收集比较对，上奖励模型或 DPO，而不是把比较对压成单一示范再 SFT——SFT 无法表达「A 比 B 好但两者都对」。若指标可自动验证：用 RL 或下一课的拒绝采样，提示集可以小，采样预算可以大。</p>',13)),(A(),s(o,null,{default:l(()=>[n(e,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E7%BC%BA%E5%8F%A3%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20S%5B%22%E7%BC%BA%E6%A0%BC%E5%BC%8F%20%2F%20%E5%8F%A3%E5%90%BB%EF%BC%9A%E7%B2%BE%E9%80%89%20SFT%22%5D%0A%20%20X%20--%3E%20P%5B%22%E7%BC%BA%E6%8E%92%E5%BA%8F%EF%BC%9A%E5%81%8F%E5%A5%BD%20%2F%20RM%22%5D%0A%20%20X%20--%3E%20R%5B%22%E7%BC%BA%E6%90%9C%E7%B4%A2%EF%BC%9A%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%A5%96%E5%8A%B1%E4%B8%8A%E7%9A%84%20RL%22%5D%0A%20%20S%20--%3E%20BASE%5B%22%E5%8F%AF%E8%A1%8C%E7%AD%96%E7%95%A5%22%5D%0A%20%20BASE%20--%3E%20P%0A%20%20BASE%20--%3E%20R%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"记账：SFT 的单位是人写或教师写的完成；RL 的单位是提示 × 采样数 × 奖励查询。比较「哪更高效」必须换算到同一人力或同一 GPU 小时，不能比「步数」。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：同样 1000 道数学题，SFT 需要人工写 1000 份完整解答；RL 只需题目加一个自动判分的验证器，每题采样 64 份答卷由机器打分——人工范文从 1000 份变成 0 份，代价换成约 64000 次生成的算力。这就是「人力换算力」的分界。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"SFT 把概率质量堆到示范轨迹上，示范外的高奖励轨迹得不到质量。RL 在参考策略附近探索，奖励把质量推向示范没写过但分数更高的完成。这解释了为何推理链任务上，SFT 蒸馏教师链很强（教师已经搜索过），纯 SFT 学生自己搜索弱；而 RL 或拒绝采样能在学生自己的分布上筛。也解释了为何无奖励的开放闲聊上，RL 容易把模型推到奖励模型癖好（冗长、阿谀），SFT 精选反而更稳。",-1)),a[7]||(a[7]=E("p",null,"概率质量放在哪里，决定了「示范之外的链」能不能被学到：",-1)),(A(),s(o,null,{default:l(()=>[n(e,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20SFTM%5B%22SFT%3A%20%E8%B4%A8%E9%87%8F%E5%A0%86%E5%88%B0%E7%A4%BA%E8%8C%83%E8%BD%A8%E8%BF%B9%E4%B8%8A%22%5D%20--%3E%20OUT%5B%22%E7%A4%BA%E8%8C%83%E5%A4%96%E7%9A%84%E9%AB%98%E5%A5%96%E5%8A%B1%E8%BD%A8%E8%BF%B9%E6%B2%A1%E6%9C%89%E8%B4%A8%E9%87%8F%22%5D%0A%20%20OUT%20--%3E%20WEAK%5B%22%E5%87%BA%E5%88%86%E5%B8%83%E5%8D%B3%E6%96%AD%3A%20%E8%87%AA%E5%B7%B1%E6%90%9C%E7%B4%A2%E5%BC%B1%22%5D%0A%20%20RLM%5B%22RL%3A%20%E5%9C%A8%E5%8F%82%E8%80%83%E7%AD%96%E7%95%A5%E9%99%84%E8%BF%91%E6%8E%A2%E7%B4%A2%22%5D%20--%3E%20SAMP%5B%22%E5%90%8C%E4%B8%80%E9%A2%98%E9%87%87%E6%A0%B7%E8%AE%B8%E5%A4%9A%20y%22%5D%0A%20%20SAMP%20--%3E%20REW%5B%22%E5%A5%96%E5%8A%B1%E6%8A%8A%E8%B4%A8%E9%87%8F%E6%8E%A8%E5%90%91%E6%B2%A1%E5%86%99%E8%BF%87%E4%BD%86%E5%88%86%E9%AB%98%E7%9A%84%E5%AE%8C%E6%88%90%22%5D%0A%20%20REW%20--%3E%20STRONG%5B%22%E5%AD%A6%E5%88%B0%E7%A4%BA%E8%8C%83%E9%87%8C%E6%B2%A1%E6%9C%89%E7%9A%84%E6%8E%A8%E7%90%86%E9%93%BE%22%5D%0A%20%20BADR%5B%22%E5%A5%96%E5%8A%B1%E8%AE%BE%E8%AE%A1%E9%94%99%E4%BA%86%22%5D%20--%3E%20HACK%5B%22Goodhart%3A%20%E5%86%97%E9%95%BF%20%2F%20%E9%98%BF%E8%B0%80%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">常见误区：初学者容易把「SFT 蒸馏教师链很强」当成学生学会了推理，实际上教师已经替学生搜索过；遇到教师没示范过的新题型，纯 SFT 学生常立刻断链。RL 的价值正是让学生在自己的分布里练搜索，而不是背现成答案。</span></p><p>遗忘：全参 RL 步子大时与全参 SFT 同类；<a href="/llm/lora">LoRA</a> 同样学得少忘得少。数据效率优势可以被灾难性遗忘抵消，监控仍要两张表。</p><p><span class="marginnote">DPO 把偏好写成分类损失，没有显式采样循环，但目标仍是「序」而不是「模仿单一 y」。它不把本课变成「只有 PPO 才算 RL」；效率上它介于成对标注与在线探索之间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有验证器又没有可靠人好时，扩大 SFT 脏合成（Alpaca 式）往往比弱奖励 RL 更可控。教师很强时，SFT 蒸馏的数据效率可以高于学生自己 RL——付的是教师 API。领域适配阶段 A 的全文 LM 也不属于本课比较。</p><p>下一课把「采样再筛再 SFT」当作中间道路：比纯 SFT 多用计算，比在线 PPO 少维护奖励模型稳定性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缺格式与口吻：精选 SFT 通常最省标注；LIMA 是这一侧的上限实验。</li><li>缺排序：用偏好对，不要压成单示范 SFT。</li><li>缺搜索且可验证：同一提示多次采样的 RL / 拒绝采样更划算。</li><li>InstructGPT 的顺序（SFT 打底再 RL）说明二者互补，不是替代。</li><li>比较效率要换算人力与采样预算，不要比原始步数。</li><li>出处：Ouyang 等，InstructGPT，NeurIPS 2022；Zhou 等，LIMA，2023；Rafailov 等，DPO，NeurIPS 2023。</li></ul>',8))])}const R=B(F,[["render",T]]);export{h as __pageData,R as default};
